{
  "name": "@xxxbrian/opencode-tps",
  "version": "0.1.1",
  "description": "Token-per-second display plugin for opencode.",
  "type": "module",
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "README.md"
  ],
  "engines": {
    "opencode": ">=1.3.14"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tokens"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/xxxbrian/opencode-tps.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": "*",
    "@opentui/keymap": "*",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": "*",
    "@opentui/keymap": "^0.2.15",
    "@opentui/solid": "*",
    "@biomejs/biome": "^2.4.15",
    "@types/node": "^25.9.1",
    "solid-js": "1.9.12",
    "typescript": "^5.9.3"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "format": "biome format --write .",
